css:
.reputesim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #e7ecf2;
    background: linear-gradient(160deg, #11161f 0%, #1a2230 100%);
    border-radius: 18px;
}

.reputesim-container * {
    box-sizing: border-box;
}

.reputesim-header {
    text-align: center;
    padding: 28px 20px 24px;
    background: linear-gradient(135deg, #2a1414 0%, #3a1f1a 45%, #5a2a1c 100%);
    color: #fdf3ee;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 12px 34px rgba(0, 0, 0, 0.45);
    border: 1px solid #6e3422;
}

.reputesim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffe7d6;
}

.reputesim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #ffcdb3;
    background: rgba(255, 255, 255, 0.08);
    padding: 5px 14px;
    border-radius: 999px;
    border: 1px solid rgba(255, 150, 110, 0.35);
}

.reputesim-subtitle {
    margin: 12px auto 0;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #f3ddd2;
}

.reputesim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #aebbcc;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.reputesim-period-counter #currentDay,
.reputesim-period-counter #maxPeriods {
    font-weight: 800;
    color: #f4d35e;
}

.reputesim-round-name {
    background: #243044;
    color: #f4d35e;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
    border: 1px solid #38465e;
}

.reputesim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #ffd9c7;
    background: #5a2418;
    padding: 4px 12px;
    border-radius: 999px;
    border: 1px solid #8a3a24;
}

.reputesim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.reputesim-status-card {
    background: #1d2532;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #2c3849;
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.30);
    border-top: 4px solid #4a5a72;
}

.reputesim-card-reputation { border-top-color: #d98324; }
.reputesim-card-engagement { border-top-color: #3aa6a0; }
.reputesim-card-rumour { border-top-color: #b0455c; }
.reputesim-card-wellbeing { border-top-color: #6c7fd8; }

.reputesim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8a98ab;
}

.reputesim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #f0f4f9;
}

.reputesim-card-reputation .reputesim-value { color: #f0a13e; }
.reputesim-card-engagement .reputesim-value { color: #4fc7c0; }
.reputesim-card-rumour .reputesim-value { color: #e06a82; }
.reputesim-card-wellbeing .reputesim-value { color: #8e9ff0; }

.reputesim-sublabel {
    font-size: 0.76rem;
    color: #7f8da0;
    line-height: 1.35;
}

.reputesim-rep-good .reputesim-value { color: #4fc7c0; }
.reputesim-rep-bad .reputesim-value { color: #e0584f; }

.reputesim-rumour-hot { border-top-color: #e0584f; }
.reputesim-rumour-hot .reputesim-value { color: #ff6f60; }
.reputesim-rumour-calm .reputesim-value { color: #4fc7c0; }

.reputesim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #161d28;
    color: #d8e0ea;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    border: 1px solid #2c3849;
}

.reputesim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #f4d35e;
}

.reputesim-briefing {
    display: flex;
    gap: 14px;
    background: #1d2532;
    border-left: 5px solid #d98324;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.28);
    border-top: 1px solid #2c3849;
    border-right: 1px solid #2c3849;
    border-bottom: 1px solid #2c3849;
}

.reputesim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.reputesim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #f0a13e;
    margin-bottom: 6px;
}

.reputesim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #cdd6e2;
}

.reputesim-briefing-text strong { color: #4fc7c0; }
.reputesim-briefing-text em { color: #ffae8a; font-style: italic; }

.reputesim-controls {
    background: #1d2532;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #2c3849;
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.28);
}

.reputesim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #f0f4f9;
    border-bottom: 2px solid #2c3849;
    padding-bottom: 8px;
}

.reputesim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #c7d2e0;
    margin: 14px 0 6px;
}

.reputesim-container select,
.reputesim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #3a485d;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #141a24;
    color: #eaf0f7;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.reputesim-container select:focus,
.reputesim-container input[type="number"]:focus {
    outline: none;
    border-color: #d98324;
    box-shadow: 0 0 0 3px rgba(217, 131, 36, 0.20);
}

.reputesim-container select option {
    background-color: #141a24;
    color: #eaf0f7;
}

.reputesim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #d98324;
}

.reputesim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #9fb0c6;
    margin-top: 4px;
}

.reputesim-range-readout span:last-child {
    color: #f0a13e;
    font-weight: 800;
}

.reputesim-hint {
    font-size: 0.8rem;
    color: #7f8da0;
    margin-top: 4px;
    line-height: 1.4;
}

.reputesim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.reputesim-container .btn-primary {
    background: linear-gradient(135deg, #d98324 0%, #b0455c 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    color: #fff;
    box-shadow: 0 6px 16px rgba(217, 131, 36, 0.30);
}

.reputesim-container .btn-primary:hover {
    filter: brightness(1.08);
}

.reputesim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #3a485d;
    color: #9fb0c6;
    background: transparent;
}

.reputesim-coach {
    background: #161d28;
    color: #d8e0ea;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.35);
    border: 1px solid #2c3849;
    border-left: 5px solid #6c7fd8;
}

.reputesim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #8e9ff0;
    margin-bottom: 8px;
}

.reputesim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.reputesim-coach-body strong { color: #f4d35e; }
.reputesim-coach-body em { color: #ffae8a; font-style: italic; }

.reputesim-history,
.reputesim-chart {
    background: #1d2532;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #2c3849;
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.28);
}

.reputesim-history h3,
.reputesim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #f0f4f9;
}

.reputesim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #cdd6e2;
}

.reputesim-container table#usfHistoryTable th {
    background: #141a24;
    color: #f4d35e;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #2c3849;
}

.reputesim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #232d3c;
}

.reputesim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #1a212d;
}

.reputesim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .reputesim-container {
        padding: 14px;
    }
    .reputesim-header h1 {
        font-size: 1.7rem;
    }
    .reputesim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .reputesim-value {
        font-size: 2rem;
    }
    .reputesim-clock {
        margin-left: 0;
    }
    .reputesim-period-counter {
        font-size: 0.88rem;
    }
    .reputesim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .reputesim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* v1.1.0 completion message (formatCompletionMessage) — self-contained, readable on the white modal */
.reputesim-completion { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #2a1c1c; }
.reputesim-cm-head { display: flex; align-items: center; gap: 18px; flex-wrap: wrap; padding-bottom: 14px; border-bottom: 1px solid rgba(42,28,28,0.15); margin-bottom: 16px; }
.reputesim-cm-score { font-size: 46px; font-weight: 800; line-height: 1; color: #a23a2e; }
.reputesim-cm-score-max { font-size: 18px; font-weight: 600; color: #6a4f4a; margin-left: 2px; }
.reputesim-cm-grade { font-size: 18px; font-weight: 700; color: #2a1c1c; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.reputesim-cm-badge { display: inline-block; font-size: 12px; font-weight: 700; letter-spacing: .02em; padding: 3px 10px; border-radius: 999px; }
.reputesim-cm-yes { background: rgba(31,111,74,0.16); color: #185a3d; }
.reputesim-cm-no { background: rgba(176,51,37,0.12); color: #b03325; }
.reputesim-cm-warn { background: rgba(180,110,20,0.16); color: #8a5410; }
.reputesim-cm-metrics { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 18px; }
.reputesim-cm-metric { flex: 1 1 110px; background: #f4efec; border: 1px solid rgba(42,28,28,0.10); border-radius: 10px; padding: 12px 14px; text-align: center; }
.reputesim-cm-mv { display: block; font-size: 22px; font-weight: 800; color: #2a1c1c; }
.reputesim-cm-ml { display: block; font-size: 12px; font-weight: 600; color: #6a4f4a; margin-top: 2px; }
.reputesim-cm-insights-title { font-size: 14px; font-weight: 700; text-transform: uppercase; letter-spacing: .04em; color: #6a4f4a; margin-bottom: 8px; }
.reputesim-cm-insights { margin: 0; padding-left: 20px; }
.reputesim-cm-insights li { font-size: 14px; line-height: 1.5; color: #34262a; margin-bottom: 8px; }

