(function() {
    'use strict';

    class ReputeAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Reputation Under Fire`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (GBP).
            this.START_REPUTATION = 55;       // brand exposed but intact
            this.START_ENGAGEMENT = 78;       // pre-crisis baseline
            this.START_RUMOUR = 30;           // already lit; ~70% if left to run
            this.START_WELLBEING = 50;        // psychological-safety asset under strain
            this.RUMOUR_UNMANAGED = 70;       // forecast spread within a day
            this.ENGAGEMENT_FLOOR = 60;       // forecast drop below 60 if unmanaged
            this.SENIOR_BILLING = 1.40;       // £1.4M combined senior billing at risk
            this.WIN_REPUTATION = 70;         // credible defensible standing
            this.WIN_RUMOUR = 35;             // contained
            this.WIN_WELLBEING = 65;          // trust preserved

            // Concept-correct answers (the strict best-scorers among siblings).
            this.RIGHT_FRAME = `coupled`;
            this.RIGHT_VERIFY = `verify`;
            this.RIGHT_POSTURE = `acknowledge`;
            this.RIGHT_INTERNAL = `early_honest`;
            this.RIGHT_ANALYST = `support_dueprocess`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    reputation: this.START_REPUTATION,
                    engagement: this.START_ENGAGEMENT,
                    rumour: this.START_RUMOUR,
                    wellbeing: this.START_WELLBEING,
                    seniorsRetained: 0,
                    coverup: false,
                    scapegoated: false,
                    seniorsLost: false,
                    reputationHistory: [this.START_REPUTATION],
                    engagementHistory: [this.START_ENGAGEMENT],
                    rumourHistory: [this.START_RUMOUR],
                    wellbeingHistory: [this.START_WELLBEING],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    frame: `coupled`,
                    verify: `verify`,
                    attention: 50,
                    posture: `acknowledge`,
                    client: `prebrief`,
                    consistency: 60,
                    internal: `early_honest`,
                    channel: `monitor`,
                    analyst: `support_dueprocess`,
                    pace: 60,
                    retention: `honest`,
                    analystDecision: `fair_lesson`,
                    governance: `real`,
                    recovery: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const fr = document.getElementById(`frameInput`);
                const ve = document.getElementById(`verifyInput`);
                const at = document.getElementById(`attentionInput`);
                if (fr) decisions.frame = fr.value;
                if (ve) decisions.verify = ve.value;
                if (at) decisions.attention = parseInt(at.value, 10);
                if (!Number.isFinite(decisions.attention) || decisions.attention < 0 || decisions.attention > 100) {
                    warn(`warn_attention_range`); return false;
                }
            } else if (round === 2) {
                const po = document.getElementById(`postureInput`);
                const cl = document.getElementById(`clientInput`);
                const co = document.getElementById(`consistencyInput`);
                if (po) decisions.posture = po.value;
                if (cl) decisions.client = cl.value;
                if (co) decisions.consistency = parseInt(co.value, 10);
                if (!Number.isFinite(decisions.consistency) || decisions.consistency < 0 || decisions.consistency > 100) {
                    warn(`warn_consistency_range`); return false;
                }
            } else if (round === 3) {
                const ic = document.getElementById(`internalInput`);
                const ch = document.getElementById(`channelInput`);
                const an = document.getElementById(`analystInput`);
                const pa = document.getElementById(`paceInput`);
                if (ic) decisions.internal = ic.value;
                if (ch) decisions.channel = ch.value;
                if (an) decisions.analyst = an.value;
                if (pa) decisions.pace = parseInt(pa.value, 10);
                if (!Number.isFinite(decisions.pace) || decisions.pace < 0 || decisions.pace > 100) {
                    warn(`warn_pace_range`); return false;
                }
            } else if (round === 4) {
                const re = document.getElementById(`retentionInput`);
                const ad = document.getElementById(`analystDecisionInput`);
                const go = document.getElementById(`governanceInput`);
                const rc = document.getElementById(`recoveryInput`);
                if (re) decisions.retention = re.value;
                if (ad) decisions.analystDecision = ad.value;
                if (go) decisions.governance = go.value;
                if (rc) decisions.recovery = parseInt(rc.value, 10);
                if (!Number.isFinite(decisions.recovery) || decisions.recovery < 0 || decisions.recovery > 100) {
                    warn(`warn_recovery_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Deltas. rumour is "lower is better": a positive rumourDelta = MORE spread (bad).
            let repDelta = 0, engDelta = 0, rumourDelta = 0, wellDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose: the two threats are one coupled crisis (Common Error 5).
                switch (d.frame) {
                    case `coupled`: repDelta += 4; engDelta += 2; rumourDelta -= 4; wellDelta += 8; coachKey = `coach_r1_coupled`; break;
                    case `external`: repDelta += 1; engDelta -= 4; rumourDelta += 6; wellDelta -= 4; coachKey = `coach_r1_external`; break;
                    case `internal`: repDelta -= 4; engDelta -= 4; rumourDelta += 4; wellDelta -= 6; coachKey = `coach_r1_internal`; break;
                    case `overblown`: repDelta -= 4; engDelta -= 4; rumourDelta += 8; wellDelta -= 4; coachKey = `coach_r1_overblown`; break;
                }

                // Verify before any public word (sets up Common Error 1 — the cover-up trap).
                switch (d.verify) {
                    case `verify`: repDelta += 4; wellDelta += 4; if (d.frame === `coupled`) coachKey = `coach_r1_sharp`; break;
                    case `assume_false`: repDelta -= 4; ds.coverup = true; coachKey = `coach_r1_assumefalse`; break;
                    case `assume_true`: repDelta -= 4; wellDelta -= 2; coachKey = `coach_r1_assumetrue`; break;
                    case `ignore`: repDelta -= 6; wellDelta -= 4; coachKey = `coach_r1_ignore`; break;
                }

                // Internal-trust attention from hour one (vs press-only focus).
                if (d.attention >= 60) { wellDelta += 4; rumourDelta -= 3; engDelta += 2; }
                else if (d.attention <= 25) { wellDelta -= 6; rumourDelta += 6; coachKey = `coach_r1_noattention`; }

                summaryKey = (d.frame === `coupled` && d.verify === `verify`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Public posture matched to actual responsibility (SCCT) — Common Error 1.
                switch (d.posture) {
                    case `acknowledge`: repDelta += 12; rumourDelta -= 4; wellDelta += 4; coachKey = `coach_r2_acknowledge`; break;
                    case `limited`: repDelta += 5; rumourDelta -= 1; coachKey = `coach_r2_limited`; break;
                    case `deny`: repDelta -= 12; rumourDelta += 8; ds.coverup = true; coachKey = `coach_r2_deny`; break;
                    case `nocomment`: repDelta -= 8; rumourDelta += 10; wellDelta -= 4; coachKey = `coach_r2_nocomment`; break;
                }

                // Client pre-brief before the story breaks.
                switch (d.client) {
                    case `prebrief`: repDelta += 6; break;
                    case `reassure`: repDelta -= 2; break;
                    case `silence`: repDelta -= 6; coachKey = (d.posture === `acknowledge`) ? coachKey : `coach_r2_clientsilence`; break;
                }

                // Internal-external consistency — the discipline that avoids the cover-up trap.
                if (d.consistency >= 60) { repDelta += 4; wellDelta += 2; }
                else if (d.consistency <= 25) { repDelta -= 6; rumourDelta += 4; coachKey = `coach_r2_inconsistent`; }

                // A flat denial WITH a low-consistency line is the worst-of-both-worlds.
                if (d.posture === `deny` && d.consistency <= 40) { repDelta -= 4; wellDelta -= 4; coachKey = `coach_r2_coverup`; }

                summaryKey = (d.posture === `acknowledge` && d.client === `prebrief` && d.consistency >= 60) ? `sum_r2_good`
                    : (d.posture === `deny` || d.posture === `nocomment` ? `sum_r2_coverup` : `sum_r2_weak`);
            } else if (round === 3) {
                // Manage the gossip & protect trust (Common Errors 2, 3, 4).
                // Internal communication: silence feeds gossip; over-disclosure breaks due process.
                switch (d.internal) {
                    case `early_honest`: rumourDelta -= 8; wellDelta += 6; engDelta += 4; coachKey = `coach_r3_early`; break;
                    case `late`: rumourDelta += 4; engDelta -= 2; coachKey = `coach_r3_late`; break;
                    case `silent`: rumourDelta += 12; wellDelta -= 6; engDelta -= 6; coachKey = `coach_r3_silent`; break;
                    case `overdisclose`: rumourDelta -= 4; wellDelta -= 8; repDelta -= 6; coachKey = `coach_r3_over`; break;
                }

                // Anonymous channel.
                switch (d.channel) {
                    case `engage`: rumourDelta -= 5; wellDelta += 4; break;
                    case `monitor`: rumourDelta -= 3; wellDelta += 2; break;
                    case `shutdown`: rumourDelta += 8; wellDelta -= 8; coachKey = `coach_r3_shutdown`; break;
                    case `ignore`: rumourDelta += 6; coachKey = (d.internal === `silent`) ? coachKey : `coach_r3_ignore`; break;
                }

                // Protect the named analyst — wellbeing & trust as strategic assets (Common Error 3).
                switch (d.analyst) {
                    case `support_dueprocess`: wellDelta += 9; engDelta += 4; rumourDelta -= 2; break;
                    case `scapegoat`: wellDelta -= 16; engDelta -= 8; ds.scapegoated = true; coachKey = `coach_r3_scapegoat`; break;
                    case `prejudge`: wellDelta -= 8; repDelta -= 4; coachKey = `coach_r3_prejudge`; break;
                }

                // Calibrated transparency: a sweet spot near 60 (not 0 silence, not 100 broadcast).
                if (d.pace >= 45 && d.pace <= 75) { rumourDelta -= 4; wellDelta += 3; }
                else if (d.pace > 90) { wellDelta -= 6; repDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r3_broadcast` : coachKey; }
                else if (d.pace < 20) { rumourDelta += 6; coachKey = (coachKey === `coach_default`) ? `coach_r3_silentpace` : coachKey; }

                summaryKey = (d.internal === `early_honest` && d.analyst === `support_dueprocess`) ? `sum_r3_good`
                    : (d.internal === `silent` ? `sum_r3_silent` : (d.analyst === `scapegoat` ? `sum_r3_scapegoat` : `sum_r3_weak`));
            } else if (round === 4) {
                // Sustain & rebuild (Common Error 6 — over-promising retention).
                // Retain the two seniors with credible, honest commitments.
                switch (d.retention) {
                    case `honest`: ds.seniorsRetained = this.SENIOR_BILLING; engDelta += 8; wellDelta += 6; repDelta += 2; coachKey = `coach_r4_honest`; break;
                    case `overpromise`: ds.seniorsRetained = 0; engDelta -= 8; wellDelta -= 8; repDelta -= 4; ds.seniorsLost = true; coachKey = `coach_r4_overpromise`; break;
                    case `nothing`: ds.seniorsRetained = 0; engDelta -= 6; ds.seniorsLost = true; coachKey = `coach_r4_nothing`; break;
                }
                // Scapegoating in R3 makes the seniors leave regardless of the R4 offer.
                if (ds.scapegoated && d.retention !== `honest`) { ds.seniorsRetained = 0; ds.seniorsLost = true; }

                // The analyst decision — fairness as a signal to the other 47.
                switch (d.analystDecision) {
                    case `fair_lesson`: wellDelta += 12; engDelta += 6; rumourDelta -= 4; coachKey = (d.retention === `honest`) ? coachKey : `coach_r4_fair`; break;
                    case `quiet`: wellDelta -= 2; rumourDelta += 4; coachKey = `coach_r4_quiet`; break;
                    case `blame`: wellDelta -= 12; engDelta -= 6; ds.scapegoated = true; coachKey = `coach_r4_blame`; break;
                }

                // Governance fix — proof of integrity vs cosmetic.
                switch (d.governance) {
                    case `real`: repDelta += 12; wellDelta += 4; rumourDelta -= 4; break;
                    case `cosmetic`: repDelta += 2; coachKey = (coachKey === `coach_default`) ? `coach_r4_cosmetic` : coachKey; break;
                    case `none`: repDelta -= 6; coachKey = `coach_r4_nogov`; break;
                }

                // Genuine wellbeing & re-engagement investment recovers the engagement score.
                if (d.recovery >= 60) { engDelta += 8; wellDelta += 6; rumourDelta -= 2; }
                else if (d.recovery >= 30) { engDelta += 3; wellDelta += 2; }
                else { engDelta -= 6; wellDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r4_norecovery` : coachKey; }

                summaryKey = (d.retention === `honest` && d.analystDecision === `fair_lesson` && d.governance === `real`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Apply deltas with clamping (0–100). Rumour is inverted: higher = worse.
            ds.reputation = Math.max(0, Math.min(100, ds.reputation + repDelta));
            ds.engagement = Math.max(0, Math.min(100, ds.engagement + engDelta));
            ds.rumour = Math.max(0, Math.min(100, ds.rumour + rumourDelta));
            ds.wellbeing = Math.max(0, Math.min(100, ds.wellbeing + wellDelta));

            // Coupling penalty: a cover-up (deny/assume-false externally while the truth diverges)
            // collapses reputation AND trust together — the worst of both worlds.
            if (ds.coverup && round >= 2) {
                ds.reputation = Math.max(0, ds.reputation - 3);
                ds.wellbeing = Math.max(0, ds.wellbeing - 3);
            }

            // Betrayal penalty (post-clamp): the two terminal R4 errors — scapegoating the analyst
            // and over-promising the seniors — must bite even when strong earlier rounds have pegged
            // the meters near their ceilings. Applied after clamping so it can't be absorbed by the
            // 0–100 cap (mirrors the cover-up coupling penalty above).
            if (round === 4) {
                if (d.analystDecision === `blame`) {
                    ds.wellbeing = Math.max(0, ds.wellbeing - 16);
                    ds.engagement = Math.max(0, ds.engagement - 10);
                    ds.rumour = Math.min(100, ds.rumour + 10);
                }
                if (d.retention === `overpromise`) {
                    ds.engagement = Math.max(0, ds.engagement - 12);
                    ds.wellbeing = Math.max(0, ds.wellbeing - 8);
                }
                if (ds.seniorsLost) {
                    ds.engagement = Math.max(0, ds.engagement - 6);
                }
                if (d.governance === `none`) {
                    ds.reputation = Math.max(0, ds.reputation - 10);
                }
            }

            ds.reputationHistory.push(Math.round(ds.reputation));
            ds.engagementHistory.push(Math.round(ds.engagement));
            ds.rumourHistory.push(Math.round(ds.rumour));
            ds.wellbeingHistory.push(Math.round(ds.wellbeing));

            // v1.1.0: publish composite (0-100) to the reporting/grading layer every period.
            ds.performance = { overallScore: this._composite(ds) };

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                reputation: Math.round(ds.reputation),
                reputationDelta: Math.round(repDelta),
                engagement: Math.round(ds.engagement),
                engagementDelta: Math.round(engDelta),
                rumour: Math.round(ds.rumour),
                rumourDelta: Math.round(rumourDelta),
                wellbeing: Math.round(ds.wellbeing),
                wellbeingDelta: Math.round(wellDelta),
                seniorsRetained: ds.seniorsRetained,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

