        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.reputationHistory.map((_, i) => (i === 0 ? `Start` : `R` + i));
            return {
                reputeChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.reputationHistory },
                        { data: ds.engagementHistory },
                        { data: ds.wellbeingHistory },
                        { data: ds.rumourHistory }
                    ]
                }
            };
        }

        // Composite (0-100) VERBATIM from v1.0.0 getPerformanceSummary (rumour inverted);
        // written to domainState.performance.overallScore each period for the reporting layer.
        _composite(ds) {
            var reputation = Math.round(ds.reputation || 0);
            var engagement = Math.round(ds.engagement || 0);
            var rumour = Math.round(ds.rumour || 0);
            var wellbeing = Math.round(ds.wellbeing || 0);
            return Math.round(reputation * 0.30 + engagement * 0.22 + wellbeing * 0.30 + (100 - rumour) * 0.18);
        }

        _cl(key, fallback) {
            try {
                if (window.mySimulation && typeof window.mySimulation.t === 'function') {
                    var v = window.mySimulation.t(key);
                    if (v && v !== key) return v;
                }
            } catch (e) {}
            return fallback;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const reputation = Math.round(ds.reputation);
            const engagement = Math.round(ds.engagement);
            const rumour = Math.round(ds.rumour);
            const wellbeing = Math.round(ds.wellbeing);

            const heldRep = reputation >= this.WIN_REPUTATION;
            const heldTeam = wellbeing >= this.WIN_WELLBEING && engagement >= this.ENGAGEMENT_FLOOR;
            const contained = rumour <= this.WIN_RUMOUR;
            const seniorsKept = ds.seniorsRetained >= this.SENIOR_BILLING - 0.001;
            // Composite: reputation + engagement + wellbeing reward, rumour penalises (inverted).
            const composite = this._composite(ds);

            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            let performanceKey = `grade_collapsed`;
            if (heldRep && heldTeam && contained && composite >= 80) performanceKey = `grade_clarity`;
            else if (heldRep && heldTeam && composite >= 70) performanceKey = `grade_held`;
            else if (ds.coverup && heldRep) performanceKey = `grade_coverup`;
            else if (heldRep && !heldTeam) performanceKey = `grade_lostteam`;
            else if (!heldRep && heldTeam) performanceKey = `grade_bruised`;
            else if (composite >= 55) performanceKey = `grade_scarred`;
            const performance = T(performanceKey);

            const insights = [];
            if (heldRep && heldTeam && contained) insights.push(window.mySimulation.t(`insight_clarity`));
            if (ds.coverup) insights.push(window.mySimulation.t(`insight_coverup`));
            if (ds.scapegoated || !seniorsKept) insights.push(window.mySimulation.t(`insight_scapegoat`));
            if (rumour > 55) insights.push(window.mySimulation.t(`insight_gossip`));
            if (wellbeing < this.WIN_WELLBEING) insights.push(window.mySimulation.t(`insight_wellbeing`));
            if (seniorsKept) insights.push(window.mySimulation.t(`insight_retained`));
            if (!insights.length) insights.push(window.mySimulation.t(`insight_mixed`));

            return {
                reputation: reputation,
                engagement: engagement,
                rumour: rumour,
                wellbeing: wellbeing,
                seniorsRetained: ds.seniorsRetained,
                heldRep: heldRep,
                heldTeam: heldTeam,
                contained: contained,
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                performanceKey: performanceKey,
                coverup: ds.coverup,
                scapegoated: ds.scapegoated,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore
                : (typeof s.composite === 'number' ? s.composite : 0);
            var grade = s.performance || (s.performanceKey ? T(s.performanceKey) : '');
            var ok = !!(s.heldRep && s.heldTeam);
            var badge = ok
                ? '<span class="reputesim-cm-badge reputesim-cm-yes">' + T('cm_met') + '</span>'
                : '<span class="reputesim-cm-badge reputesim-cm-no">' + T('cm_missed') + '</span>';
            var failBadge = (s.coverup || s.scapegoated)
                ? '<span class="reputesim-cm-badge reputesim-cm-warn">' + T('cm_failstate_badge') + '</span>'
                : '';
            var insights = Array.isArray(s.insights) ? s.insights : [];
            var items = insights.map(function(t) { return '<li>' + t + '</li>'; }).join('');
            var metrics = ''
                + '<div class="reputesim-cm-metric"><span class="reputesim-cm-mv">' + Math.round(s.reputation || 0) + '</span><span class="reputesim-cm-ml">' + T('cm_m_reputation') + '</span></div>'
                + '<div class="reputesim-cm-metric"><span class="reputesim-cm-mv">' + Math.round(s.engagement || 0) + '</span><span class="reputesim-cm-ml">' + T('cm_m_engagement') + '</span></div>'
                + '<div class="reputesim-cm-metric"><span class="reputesim-cm-mv">' + Math.round(s.wellbeing || 0) + '</span><span class="reputesim-cm-ml">' + T('cm_m_wellbeing') + '</span></div>'
                + '<div class="reputesim-cm-metric"><span class="reputesim-cm-mv">' + Math.round(s.rumour || 0) + '</span><span class="reputesim-cm-ml">' + T('cm_m_rumour') + '</span></div>';
            return ''
                + '<div class="reputesim-completion">'
                +   '<div class="reputesim-cm-head">'
                +     '<div class="reputesim-cm-score">' + score + '<span class="reputesim-cm-score-max">/100</span></div>'
                +     '<div class="reputesim-cm-grade">' + grade + ' ' + badge + failBadge + '</div>'
                +   '</div>'
                +   '<div class="reputesim-cm-metrics">' + metrics + '</div>'
                +   '<div class="reputesim-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="reputesim-cm-insights">' + items + '</ul>'
                + '</div>';
        }

        getHint(state, results) {
