            if (ds.reputation < 40 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_reputation`);
            if (ds.reputation >= this.WIN_REPUTATION && ds.wellbeing >= this.WIN_WELLBEING && ds.rumour <= this.WIN_RUMOUR) return window.mySimulation.t(`hint_strong`);
